import { describe, expect, test } from "bun:test";
import { render } from "../src/engine";

describe("render", () => {
  test("escapes values and supports raw values and comments", () => {
    expect(render("A {{value}} B {{{value}}}{{! ignored }}", { value: `&<>\"'` }))
      .toBe("A &amp;&lt;&gt;&quot;&#39; B &<>\"'");
