    expect(render("x{{missing.deep}}y", {})).toBe("xy");
  });

  test("handles if truthiness, nesting, and else", () => {
    expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: [], b: true }))
